def match(orders):
    trades = []
    buy_book = []  # [(price, arrival_time, id, qty), ...]
    sell_book = []  # [(price, arrival_time, id, qty), ...]
    order_map = {}  # id -> (side, price, qty, arrival_time) for resting orders
    arrival_time = 0

    for order in orders:
        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, price, qty, arr_time = order_map[order_id]
                del order_map[order_id]
                if side == 'buy':
                    buy_book = [(p, t, oid, q) for p, t, oid, q in buy_book if oid != order_id]
                else:
                    sell_book = [(p, t, oid, q) for p, t, oid, q in sell_book if oid != order_id]
            continue

        order_type = order[0]
        order_id = order[1]
        side = order[2]

        if order_type == 'market':
            qty = order[3]
            price = None
        else:
            price = order[3]
            qty = order[4]

        remaining_qty = qty

        if side == 'buy':
            # Match against sell_book
            while remaining_qty > 0 and sell_book:
                sell_price, sell_time, sell_id, sell_qty = sell_book[0]

                if order_type == 'market' or sell_price <= price:
                    match_qty = min(remaining_qty, sell_qty)
                    trades.append([order_id, sell_id, sell_price, match_qty])
                    remaining_qty -= match_qty

                    if match_qty == sell_qty:
                        sell_book.pop(0)
                        if sell_id in order_map:
                            del order_map[sell_id]
                    else:
                        sell_book[0] = (sell_price, sell_time, sell_id, sell_qty - match_qty)
                        order_map[sell_id] = ('sell', sell_price, sell_qty - match_qty, sell_time)
                else:
                    break

            # Add remainder to buy_book if limit order
            if remaining_qty > 0 and order_type == 'limit':
                buy_book.append((price, arrival_time, order_id, remaining_qty))
                order_map[order_id] = ('buy', price, remaining_qty, arrival_time)
                # Sort by price descending, then by arrival_time ascending
                buy_book.sort(key=lambda x: (-x[0], x[1]))

        else:  # side == 'sell'
            # Match against buy_book
            while remaining_qty > 0 and buy_book:
                buy_price, buy_time, buy_id, buy_qty = buy_book[0]

                if order_type == 'market' or buy_price >= price:
                    match_qty = min(remaining_qty, buy_qty)
                    trades.append([buy_id, order_id, buy_price, match_qty])
                    remaining_qty -= match_qty

                    if match_qty == buy_qty:
                        buy_book.pop(0)
                        if buy_id in order_map:
                            del order_map[buy_id]
                    else:
                        buy_book[0] = (buy_price, buy_time, buy_id, buy_qty - match_qty)
                        order_map[buy_id] = ('buy', buy_price, buy_qty - match_qty, buy_time)
                else:
                    break

            # Add remainder to sell_book if limit order
            if remaining_qty > 0 and order_type == 'limit':
                sell_book.append((price, arrival_time, order_id, remaining_qty))
                order_map[order_id] = ('sell', price, remaining_qty, arrival_time)
                # Sort by price ascending, then by arrival_time ascending
                sell_book.sort(key=lambda x: (x[0], x[1]))

        arrival_time += 1

    return trades

